from collections import deque

g = {1: [4, 3], 2: [], 3: [2, 5], 4: [6], 5: [6], 6: []}

def bfs(s):
    seen, q, out = {s}, deque([s]), []
    while q:
        v = q.popleft()
        out.append(v)
        for w in g[v]:
            if w not in seen:
                seen.add(w)
                q.append(w)
    return out

